  {
   "name": "laps",
   "type": "number"
  },
  {
   "name": "trend",
   "expr": "SPARKLINE(@laps)"
  },
  {
   "name": "best",
   "expr": "MIN(@laps)"
  },
  {
   "name": "average",
   "expr": "ROUND(AVERAGE(@laps), 1)"
  },
  {
   "name": "fade",
   "expr": "INDEX(@laps, COUNT(@laps)) - INDEX(@laps, 1)"
  },
  {
   "name": "pacing",
   "expr": "IF(@fade > 2, \"Fading\", IF(@fade < -2, \"Negative split\", \"Even\"))"
  },
  {
   "name": "on_goal",
   "expr": "FILTER(@laps, @laps <= @goal, \"none\")"
  },
  {
   "name": "splits",
   "expr": "SCAN(0, @laps, LAMBDA(total, lap, total + lap))"
  },
  {
   "name": "gap",
   "expr": "@best - MIN(laps)"
  },
  {
   "name": "rank",
   "expr": "RANK(@best, best, 1)"
  }
